mapper.select:
SELECT base_count,
       add_count,
       total_count,
       class_key,
       unit_key,
       center_code,
       user_code,
       yy,
       mm
FROM erp_order
WHERE center_code = #{centerCode}
  AND class_key = #{classKey}
  AND unit_key = #{unitKey}
  AND yy = #{yy}
  ANd mm = #{mm}

mapper.update:
UPDATE erp_order
SET add_count   = #{addCount},
    total_count = #{totalCount},
    updated_at  = SYSDATETIME()
WHERE center_code = #{centerCode}
  AND class_key = #{classKey}
  AND unit_key = #{unitKey}
  AND yy = #{yy}
  AND mm = #{mm}

update.foreach:
UPDATE erp_class_fee_map
SET fee = #{item.fee}
WHERE class_key = #{item.classKey}
AND center_code = #{item.centerCode}
